"""Generate the TypeScript client of the internal API from its OpenAPI schema.

uv run manage.py generate_api_client            # writes assets/editor/api/client.ts
uv run manage.py generate_api_client --check    # fails when the file is stale (CI)
"""

import re
from pathlib import Path

from django.conf import settings
from django.core.management.base import BaseCommand, CommandError

from lorebook.api import api

OUTPUT = Path(settings.BASE_DIR) / "assets" / "editor" / "api" / "client.ts"

HEADER = """\
// Generated by `uv run manage.py generate_api_client` from the OpenAPI schema
// of the internal API (lorebook/api.py). Do not edit by hand.
/* eslint-disable */

export class ApiError extends Error {
  constructor(
    public status: number,
    public detail: unknown,
  ) {
    super(`API error ${status}`);
  }
}

export interface ClientOptions {
  baseUrl: string;
  csrfToken: () => string;
}

let options: ClientOptions = { baseUrl: "/api/", csrfToken: () => "" };

export function configure(next: Partial<ClientOptions>) {
  options = { ...options, ...next };
}

async function request<T>(
  method: string,
  path: string,
  body?: unknown,
  form?: FormData,
): Promise<T> {
  const headers: Record<string, string> = { Accept: "application/json" };
  if (method !== "GET") headers["X-CSRFToken"] = options.csrfToken();
  let payload: BodyInit | undefined;
  if (form) {
    payload = form;
  } else if (body !== undefined) {
    headers["Content-Type"] = "application/json";
    payload = JSON.stringify(body);
  }
  const response = await fetch(options.baseUrl.replace(/\\/$/, "") + path, {
    method,
    headers,
    body: payload,
    credentials: "same-origin",
  });
  const text = await response.text();
  const data = text ? JSON.parse(text) : undefined;
  if (!response.ok) throw new ApiError(response.status, data?.detail ?? data);
  return data as T;
}
"""


def ts_type(schema: dict) -> str:
    if "$ref" in schema:
        return schema["$ref"].rsplit("/", 1)[-1]
    if "anyOf" in schema:
        return " | ".join(ts_type(item) for item in schema["anyOf"])
    kind = schema.get("type")
    if kind == "string":
        if schema.get("format") == "binary":
            return "Blob"
        if "enum" in schema:
            return " | ".join(f'"{value}"' for value in schema["enum"])
        return "string"
    if kind in ("integer", "number"):
        return "number"
    if kind == "boolean":
        return "boolean"
    if kind == "null":
        return "null"
    if kind == "array":
        return f"{ts_type(schema.get('items', {}))}[]"
    if kind == "object" or "properties" in schema:
        if "properties" in schema:
            return "{ " + "; ".join(property_lines(schema)) + " }"
        extra = schema.get("additionalProperties")
        if isinstance(extra, dict) and extra:
            return f"Record<string, {ts_type(extra)}>"
        return "Record<string, unknown>"
    return "unknown"


def property_lines(schema: dict) -> list[str]:
    required = set(schema.get("required", []))
    return [
        f"{name}{'' if name in required else '?'}: {ts_type(prop)}"
        for name, prop in schema.get("properties", {}).items()
    ]


def camel(name: str) -> str:
    head, *tail = name.split("_")
    return head + "".join(part.capitalize() for part in tail)


def generate() -> str:
    schema = api.get_openapi_schema()
    lines = [HEADER]
    for name, component in sorted(schema.get("components", {}).get("schemas", {}).items()):
        lines.append(f"export interface {name} {{")
        lines += [f"  {line};" for line in property_lines(component)]
        lines.append("}\n")

    for path, methods in sorted(schema["paths"].items()):
        for method, operation in methods.items():
            function = camel(operation["operationId"].rsplit("_api_", 1)[-1])
            params = [p for p in operation.get("parameters", []) if p["in"] == "path"]
            args = [f"{camel(p['name'])}: {ts_type(p['schema'])}" for p in params]
            body = operation.get("requestBody", {}).get("content", {})
            call_body, call_form = "undefined", "undefined"
            if "application/json" in body:
                args.append(f"body: {ts_type(body['application/json']['schema'])}")
                call_body = "body"
            elif "multipart/form-data" in body:
                args.append("form: FormData")
                call_form = "form"
            responses = {str(code): value for code, value in operation.get("responses", {}).items()}
            success = next((code for code in ("200", "201") if code in responses), None)
            result = "void"
            if success:
                content = responses[success].get("content", {}).get("application/json")
                if content:
                    result = ts_type(content["schema"])
            url = re.sub(
                r"\{(\w+)\}",
                lambda match: "${" + camel(match.group(1)) + "}",
                path.removeprefix("/api"),
            )
            call = f'"{method.upper()}", `{url}`, {call_body}, {call_form}'
            lines.append(
                f"export function {function}({', '.join(args)}): Promise<{result}> {{\n"
                f"  return request<{result}>({call});\n"
                "}\n"
            )
    return "\n".join(lines)


class Command(BaseCommand):
    help = "Generate the TypeScript client of the internal API."

    def add_arguments(self, parser):
        parser.add_argument("--check", action="store_true", help="Fail if the client is stale.")

    def handle(self, *args, check=False, **options):
        code = generate()
        if check:
            if not OUTPUT.exists() or OUTPUT.read_text() != code:
                raise CommandError("The API client is stale: run `manage.py generate_api_client`.")
            self.stdout.write(self.style.SUCCESS("The API client is up to date."))
            return
        OUTPUT.parent.mkdir(parents=True, exist_ok=True)
        OUTPUT.write_text(code)
        self.stdout.write(self.style.SUCCESS(f"Wrote {OUTPUT.relative_to(settings.BASE_DIR)}"))
